  const items = [
    'Auswahl1',
    'Auswahl2',
    'Auswahl3'
  ];

  return (
    <>
      <ul className="GroupList">
        {items.map((item, index) => (
          <li key={index}>{item}</li>
        ))}
      </ul>
    </>
  );
}
